ALTER TABLE public.voucher_items ADD COLUMN dispatch_id uuid;
CREATE FUNCTION public.claim_voucher_chunk(rid uuid, amount integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids uuid[]; lease uuid:=gen_random_uuid(); output jsonb; BEGIN IF amount NOT IN (25,50,100) THEN RAISE EXCEPTION 'invalid_chunk'; END IF; PERFORM pg_advisory_xact_lock(hashtext(rid::text)); IF EXISTS(SELECT 1 FROM voucher_items WHERE router_id=rid AND state='sent' AND lease_at>=now()-interval '2 minutes') THEN RETURN NULL; END IF; UPDATE voucher_items SET state='uncertain',result='confirmation_timeout' WHERE router_id=rid AND state='sent' AND lease_at<now()-interval '2 minutes' AND attempts>=3; SELECT array_agg(id) INTO ids FROM (SELECT vi.id FROM voucher_items vi JOIN voucher_batches vb ON vb.id=vi.batch_id JOIN voucher_secrets vs ON vs.item_id=vi.id WHERE vi.router_id=rid AND vb.state='pending' AND vi.secret_valid AND vi.attempts<3 AND (vi.state='pending' OR (vi.state='sent' AND vi.lease_at<now()-interval '2 minutes')) ORDER BY vb.created_at,vi.ordinal LIMIT amount FOR UPDATE OF vi) q; IF ids IS NULL THEN RETURN NULL; END IF; UPDATE voucher_items SET state='sent',lease_at=now(),attempts=attempts+1,dispatch_id=lease WHERE id=ANY(ids); SELECT jsonb_build_object('lease',lease,'items',jsonb_agg(jsonb_build_object('item',to_jsonb(vi),'batch',to_jsonb(vb)) ORDER BY vb.created_at,vi.ordinal)) INTO output FROM voucher_items vi JOIN voucher_batches vb ON vb.id=vi.batch_id WHERE vi.id=ANY(ids); RETURN output; END $$;
CREATE FUNCTION public.confirm_voucher_chunk(rid uuid, lease uuid, results jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; BEGIN IF jsonb_array_length(results) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'invalid_results'; END IF; PERFORM pg_advisory_xact_lock(hashtext(rid::text)); FOR r IN SELECT value FROM jsonb_array_elements(results) LOOP IF r->>'result' NOT IN ('ok','error') OR NOT EXISTS(SELECT 1 FROM voucher_items WHERE id=(r->>'item')::uuid AND router_id=rid AND dispatch_id=lease) THEN RAISE EXCEPTION 'invalid_result'; END IF; PERFORM confirm_voucher_item((r->>'item')::uuid,rid,r->>'result'); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.claim_voucher_chunk(uuid,integer),public.confirm_voucher_chunk(uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_voucher_chunk(uuid,integer),public.confirm_voucher_chunk(uuid,uuid,jsonb) TO service_role;